  guideTitle: "Runner Rug Size Guide: Width, Length and the Floor Border",
  metaTitle: "Runner Rug Size Guide",
  metaDescription: "Match runner width to the hallway, leave a floor border, size the length against doors and use runners beside sofas, beds and entries without tripping.",
  heroImage: "/images/articles/runner-size-hero.webp",
